import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios'

type Tokens = { accessToken: string; refreshToken: string }
let tokens: Tokens | null = null
let refreshPromise: Promise<Tokens> | null = null
const baseURL = import.meta.env.VITE_API_BASE_URL ?? 'http://127.0.0.1:5000/api/v1'

export const apiClient = axios.create({ baseURL, timeout: 15_000 })

/**
 * The hosted API sleeps when idle and takes up to a minute to wake. Calling this as the app opens
 * starts the wake-up while the person is still signing in. It carries no credentials and its
 * result is ignored: a failure here changes nothing, the real requests report their own errors.
 */
export function warmUpApi() {
  void fetch(`${baseURL.replace(/\/api\/v1\/?$/, '')}/health`, { mode: 'no-cors', cache: 'no-store' }).catch(() => undefined)
}

// Only the refresh token is kept, and only for the life of the tab: a reload restores the session,
// closing the tab ends it. The access token never leaves memory.
const refreshTokenKey = 'familyveda.refreshToken'

function readStoredRefreshToken(): string | null {
  try {
    return sessionStorage.getItem(refreshTokenKey)
  } catch {
    return null
  }
}

function storeRefreshToken(refreshToken: string | null) {
  try {
    if (refreshToken) sessionStorage.setItem(refreshTokenKey, refreshToken)
    else sessionStorage.removeItem(refreshTokenKey)
  } catch {
    // Storage can be blocked (private mode, site data disabled); the session then lasts until reload.
  }
}

export function hasStoredSession() {
  return readStoredRefreshToken() !== null
}

export function setSessionTokens(next: Tokens | null) {
  tokens = next
  storeRefreshToken(next?.refreshToken ?? null)
}

apiClient.interceptors.request.use((config: InternalAxiosRequestConfig) => {
  if (tokens?.accessToken) config.headers.Authorization = `Bearer ${tokens.accessToken}`
  return config
})

apiClient.interceptors.response.use(undefined, async (error: AxiosError) => {
  const original = error.config as (InternalAxiosRequestConfig & { _retried?: boolean }) | undefined
  if (error.response?.status !== 401 || !original || original._retried || !tokens?.refreshToken) throw error

  original._retried = true
  refreshPromise ??= axios.post<AuthResponse>(`${baseURL}/auth/refresh`, { refreshToken: tokens.refreshToken })
    .then(({ data }) => {
      const next = { accessToken: data.accessToken, refreshToken: data.refreshToken }
      setSessionTokens(next)
      return next
    })
    .finally(() => { refreshPromise = null })

  try {
    const next = await refreshPromise
    original.headers.Authorization = `Bearer ${next.accessToken}`
    return apiClient(original)
  } catch {
    setSessionTokens(null)
    window.dispatchEvent(new Event('familyveda:session-expired'))
    throw error
  }
})

/**
 * Re-issues the session from the server (e.g. after the Family Head role changes hands), so the new
 * role reaches the UI without signing in again. Returns null when there is no session to refresh.
 */
export async function refreshSession(): Promise<AuthResponse | null> {
  if (!tokens?.refreshToken) return null
  const { data } = await axios.post<AuthResponse>(`${baseURL}/auth/refresh`, { refreshToken: tokens.refreshToken })
  setSessionTokens({ accessToken: data.accessToken, refreshToken: data.refreshToken })
  return data
}

/**
 * Re-issues the session after a page reload from the refresh token kept for this tab. Returns null
 * when there is nothing to restore or the server no longer accepts the token.
 */
export async function restoreStoredSession(): Promise<AuthResponse | null> {
  const refreshToken = readStoredRefreshToken()
  if (!refreshToken) return null
  try {
    // The hosted API can take up to a minute to wake, so this waits longer than a normal request.
    const { data } = await axios.post<AuthResponse>(`${baseURL}/auth/refresh`, { refreshToken }, { timeout: 70_000 })
    setSessionTokens({ accessToken: data.accessToken, refreshToken: data.refreshToken })
    return data
  } catch (error) {
    // A rejected token is discarded; a network failure keeps it so the next reload can try again.
    if (axios.isAxiosError(error) && error.response) setSessionTokens(null)
    return null
  }
}

export type AuthResponse = {
  userId: string
  displayName: string
  userType: 'FamilyUser' | 'Doctor' | 'Admin'
  familyRole?: 'Head' | 'AdultMember' | 'MinorMember' | null
  doctorVerificationStatus?: 'Pending' | 'Verified' | 'MoreInformationRequired' | 'Rejected' | 'Suspended' | null
  familyHeadVerificationStatus?: 'Pending' | 'Verified' | 'MoreInformationRequired' | 'Rejected' | 'Suspended' | null
  familyCode?: string | null
  accessToken: string
  refreshToken: string
  accessTokenExpiresAt: string
}

