/** Family-level roster: names and roles only, never another adult's DOB or health data. */
export type RosterMemberDto = { id: string; displayName: string; role: 'Head' | 'AdultMember' | 'MinorMember'; isMinor: boolean; isSelf: boolean; hasAccount: boolean }
export type FamilyInvitationSummaryDto = {
  id: string
  emailMasked?: string | null
  relationshipType?: string | null
  status: 'Pending' | 'Accepted' | 'Cancelled' | 'Expired'
  createdAt: string
  expiresAt: string
}
export type FamilyInvitationDto = { id: string; token: string; expiresAt: string }
export type MembershipChangeDto = { memberId: string; familyId: string; familyName: string; familyCode?: string | null }
export type HeadTransferDto = {
  id: string
  familyId: string
  familyName: string
  fromMemberId: string
  fromDisplayName: string
  toMemberId: string
  toDisplayName: string
  status: 'Pending' | 'Accepted' | 'Declined' | 'Cancelled'
  createdAt: string
  respondedAt?: string | null
}

/** An invitation sent to the signed-in user's own email; approved or rejected in-app without a token. */
export interface IncomingInvitationDto {
  id: string
  familyName: string
  invitedByName: string
  relationshipType?: string | null
  createdAt: string
  expiresAt: string
  canApprove: boolean
  blockedReason?: string | null
}

export const familyLifecycleApi = {
  getIncomingInvitations: () => apiClient.get<IncomingInvitationDto[]>('/invitations/incoming'),
  approveInvitation: (invitationId: string) => apiClient.post<MembershipChangeDto>(`/invitations/${invitationId}/approve`),
  rejectInvitation: (invitationId: string) => apiClient.post(`/invitations/${invitationId}/reject`),
  getRoster: (familyId: string) => apiClient.get<RosterMemberDto[]>(`/families/${familyId}/roster`),
  getInvitations: (familyId: string) => apiClient.get<FamilyInvitationSummaryDto[]>(`/families/${familyId}/invitations`),
  createInvitation: (familyId: string, body: { email: string; relationshipType?: string }) =>
    apiClient.post<FamilyInvitationDto>(`/families/${familyId}/invitations`, body),
  resendInvitation: (familyId: string, invitationId: string, email: string) =>
    apiClient.post<FamilyInvitationDto>(`/families/${familyId}/invitations/${invitationId}/resend`, { email }),
  cancelInvitation: (familyId: string, invitationId: string) =>
    apiClient.post(`/families/${familyId}/invitations/${invitationId}/cancel`),
  removeFromFamily: (memberId: string) => apiClient.post<MembershipChangeDto>(`/members/${memberId}/remove-from-family`),
  leaveFamily: (startOwnFamily: boolean) => apiClient.post<MembershipChangeDto>('/families/me/leave', { startOwnFamily }),
  renameFamily: (familyId: string, name: string) => apiClient.put<FamilyDto>(`/families/${familyId}`, { name }),
  // FH-3 Family Head transfer. GET endpoints answer 204 (empty body) when nothing is waiting.
  proposeHeadTransfer: (familyId: string, toMemberId: string) =>
    apiClient.post<HeadTransferDto>(`/families/${familyId}/head-transfers`, { toMemberId }),
  getPendingHeadTransfer: (familyId: string) => apiClient.get<HeadTransferDto | ''>(`/families/${familyId}/head-transfers/pending`),
  getIncomingHeadTransfer: () => apiClient.get<HeadTransferDto | ''>('/families/head-transfers/incoming'),
  acceptHeadTransfer: (id: string) => apiClient.post<HeadTransferDto>(`/families/head-transfers/${id}/accept`),
  declineHeadTransfer: (id: string) => apiClient.post<HeadTransferDto>(`/families/head-transfers/${id}/decline`),
  cancelHeadTransfer: (id: string) => apiClient.post<HeadTransferDto>(`/families/head-transfers/${id}/cancel`),
}

export const threePortalApi = {
  getFamilyDashboard: () => apiClient.get<FamilyDashboardSummaryDto>('/dashboard/family'),
  getDoctorDashboard: () => apiClient.get<DoctorDashboardSummaryDto>('/dashboard/doctor'),

  submitJoinRequest: (body: { familyCode: string; relationshipType: string; message?: string }) =>
    apiClient.post<JoinRequestDto>('/families/join-requests', body),
  getMyJoinRequests: () => apiClient.get<JoinRequestDto[]>('/families/join-requests/mine'),
  getFamilyJoinRequests: (familyId: string, status = 'Pending') =>
    apiClient.get<JoinRequestDto[]>(`/families/${familyId}/join-requests`, { params: { status } }),
  acceptJoinRequest: (id: string) => apiClient.post(`/families/join-requests/${id}/accept`),
  declineJoinRequest: (id: string) => apiClient.post(`/families/join-requests/${id}/decline`),

  getDoctorDirectory: (params?: { search?: string; district?: string }) =>
    apiClient.get<DoctorSummaryDto[]>('/doctors/directory', { params }),
  getFamilyDoctor: (familyId: string) => apiClient.get<DoctorSummaryDto | null>(`/families/${familyId}/doctor`),
  requestFamilyDoctor: (familyId: string, body: { doctorId: string; message?: string }) =>
    apiClient.post<DoctorRequestDto>(`/families/${familyId}/doctor-requests`, body),
  getPendingFamilyDoctorRequest: (familyId: string) =>
    apiClient.get<DoctorRequestDto | null>(`/families/${familyId}/doctor-requests/pending`),
  cancelFamilyDoctorRequest: (familyId: string, id: string) =>
    apiClient.post<DoctorRequestDto>(`/families/${familyId}/doctor-requests/${id}/cancel`),
  getMyFamilyDoctorRequests: () => apiClient.get<DoctorRequestDto[]>('/doctors/me/family-requests'),
  acceptFamilyDoctorRequest: (id: string) => apiClient.post(`/doctors/me/family-requests/${id}/accept`),
  declineFamilyDoctorRequest: (id: string) => apiClient.post(`/doctors/me/family-requests/${id}/decline`),

  bookAppointment: (body: { memberId: string; startsAt: string; durationMinutes?: number; reason: string }) =>
    apiClient.post<AppointmentDto>('/appointments', body),
  getMyAppointments: () => apiClient.get<AppointmentDto[]>('/appointments/mine'),
  cancelAppointment: (id: string) => apiClient.post(`/appointments/${id}/cancel`),
  getDoctorAppointments: (params?: { from?: string; to?: string }) =>
    apiClient.get<AppointmentDto[]>('/doctors/me/appointments', { params }),
  setAppointmentStatus: (id: string, action: 'confirm' | 'complete' | 'no-show' | 'cancel', note?: string) =>
    apiClient.post<AppointmentDto>(`/doctors/me/appointments/${id}/${action}`, { note }),

  getNotifications: (unreadOnly?: boolean) =>
    apiClient.get<NotificationDto[]>('/notifications', { 
      params: { 
        ...(unreadOnly ? { unreadOnly: true } : {}),
        // Cache-buster to prevent stale bell counts
        _t: Date.now()
      } 
    }),
  markNotificationRead: (id: string) => apiClient.post(`/notifications/${id}/read`),
}

